    local inputKeyFull = ""
    local function truncateKey(key)
        if not key then
            return ""
        end
        if #key <= 9 then
            return key
        end
        return key:sub(1, #key - 9) .. "..."
    end

    TextBox.Focused:Connect(function()
        if inputKeyFull ~= "" then
            TextBox.Text = inputKeyFull
        end
    end)

    TextBox.FocusLost:Connect(function()
        if inputKeyFull ~= "" and TextBox.Text == inputKeyFull then
            TextBox.Text = truncateKey(inputKeyFull)
            return
        end

        local current = TextBox.Text or ""
        if current ~= "" then
            inputKeyFull = current
            TextBox.Text = truncateKey(inputKeyFull)
        else
            inputKeyFull = ""
        end
    end)

    local function getTextBoxKey()
        if inputKeyFull ~= "" then
            return inputKeyFull
        end
        return TextBox.Text or ""
    end

