    RandomStuff.FontFace = Font.new("rbxasset://fonts/families/HighwayGothic.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
    RandomStuff.Text = "Did you know? Oshiru used to be Kalitor!"
    RandomStuff.TextColor3 = Color3.fromRGB(75, 75, 75)
    RandomStuff.TextSize = 12
    RandomStuff.AutomaticSize = Enum.AutomaticSize.None
    RandomStuff.Parent = BFrame

    RandomStuffPadding.PaddingLeft = UDim.new(0, 1)
    RandomStuffPadding.Parent = RandomStuff

    local function createGameEntry(gameName, imageLink)
        local GameBackground = Instance.new("Frame")
        local GameBackgroundCorner = Instance.new("UICorner")
        local GameBackgroundStroke = Instance.new("UIStroke")
        local GameTitle = Instance.new("TextLabel")
        local GameTitlePadding = Instance.new("UIPadding")
        local GamesImage = Instance.new("ImageLabel")
        local GamesImageCorner = Instance.new("UICorner")

        GameBackground.Name = "GameBackground"
        GameBackground.AnchorPoint = Vector2.new(0.5, 0.5)
        GameBackground.Position = UDim2.new(0.5, 0, 0.827, 0)
        GameBackground.Size = UDim2.new(0, 160, 0, 30)
        GameBackground.BorderSizePixel = 0
        GameBackground.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
        GameBackground.AutomaticSize = Enum.AutomaticSize.XY
        GameBackground.ClipsDescendants = true
        GameBackground.Parent = ScrollingFrame

        GameBackgroundCorner.CornerRadius = UDim.new(0, 8)
        GameBackgroundCorner.Parent = GameBackground

        GameBackgroundStroke.Color = Color3.fromRGB(30, 30, 30)
        GameBackgroundStroke.Thickness = 1
        GameBackgroundStroke.Parent = GameBackground

        GameTitle.Name = "GameTitle"
        GameTitle.AnchorPoint = Vector2.new(0.5, 0.5)
        GameTitle.Position = UDim2.new(0.299, 0, 0.336, 0)
        GameTitle.Size = UDim2.new(0, 100, 0, 30)
        GameTitle.BackgroundTransparency = 1
        GameTitle.FontFace = Font.new("rbxasset://fonts/families/HighwayGothic.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
        GameTitle.Text = gameName or "Games"
        GameTitle.TextColor3 = Color3.fromRGB(255, 255, 255)
        GameTitle.TextSize = 10
        GameTitle.TextXAlignment = Enum.TextXAlignment.Left
        GameTitle.ZIndex = 999
        GameTitle.LayoutOrder = 3
        GameTitle.Parent = GameBackground

        GameTitlePadding.PaddingLeft = UDim.new(0, 10)
        GameTitlePadding.Parent = GameTitle

        GamesImage.Name = "GamesImage"
        GamesImage.AnchorPoint = Vector2.new(0.5, 0.5)
        GamesImage.Position = UDim2.new(0.5, 0, 0.5, 0)
        GamesImage.Size = UDim2.new(1, 0, 1, 0)
        GamesImage.BackgroundTransparency = 1
        GamesImage.Image = imageLink or ""
        GamesImage.ImageColor3 = Color3.fromRGB(50, 50, 50)
        GamesImage.ClipsDescendants = true
        GamesImage.LayoutOrder = 2
        GamesImage.Parent = GameBackground
        GamesImage.ScaleType = Enum.ScaleType.Crop

        GamesImageCorner.CornerRadius = UDim.new(0, 8)
        GamesImageCorner.Parent = GamesImage

        return GameBackground
    end

    local function populateSupportedGames()
        for _, gameData in ipairs(supportedGamesImages) do
            createGameEntry(gameData.name, gameData.image)
        end
    end

    getgenv().addSupportedGameToUI = function(gameName, imageLink)
        return createGameEntry(gameName, imageLink)
    end

    local player = Players.LocalPlayer
    if player then
        local userId = player.UserId
        local thumbType = Enum.ThumbnailType.HeadShot
        local thumbSize = Enum.ThumbnailSize.Size420x420
        local content, isReady = Players:GetUserThumbnailAsync(userId, thumbType, thumbSize)
        UserProfile.Image = content
        UserDisplayName.Text = player.DisplayName
        table.insert(imagesToPreload, content)
    end

    local dragging, dragInput, dragStart, startPos

    local function updateDrag(input)
        local delta = input.Position - dragStart
        BFrame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
    end

    Header.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = BFrame.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                end
            end)
        end
    end)

    Header.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)

    UIS.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            updateDrag(input)
        end
    end)

    local isMinimized = false
    local isMobile = UIS.TouchEnabled and not UIS.KeyboardEnabled

    local function restoreDesktop()
        isMinimized = false

        local sizeTweenInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local sizeTween = TweenService:Create(BFrame, sizeTweenInfo, {
