            local transparencyTweenInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

            TweenService:Create(UserSection, transparencyTweenInfo, {BackgroundTransparency = 0}):Play()
            TweenService:Create(UserSectionStroke, transparencyTweenInfo, {Transparency = 0}):Play()
            TweenService:Create(UserInfo, transparencyTweenInfo, {BackgroundTransparency = 0}):Play()
            TweenService:Create(UserProfile, transparencyTweenInfo, {ImageTransparency = 0}):Play()
            TweenService:Create(Greeting, transparencyTweenInfo, {TextTransparency = 0}):Play()
            TweenService:Create(UserDisplayName, transparencyTweenInfo, {TextTransparency = 0}):Play()
            TweenService:Create(SupportedGames, transparencyTweenInfo, {BackgroundTransparency = 0}):Play()
            TweenService:Create(SupportedGamesStroke, transparencyTweenInfo, {Transparency = 0}):Play()
