            TweenService:Create(TextBoxBackground, transparencyTweenInfo, {BackgroundTransparency = 0}):Play()
            TweenService:Create(TextBoxBackgroundStroke, transparencyTweenInfo, {Transparency = 0}):Play()
            TweenService:Create(TextBox, transparencyTweenInfo, {TextTransparency = 0}):Play()
            TweenService:Create(GetKeyBackground, transparencyTweenInfo, {BackgroundTransparency = 0}):Play()
            TweenService:Create(GetKeyBackgroundStroke, transparencyTweenInfo, {Transparency = 0}):Play()
            TweenService:Create(GetKeyButton, transparencyTweenInfo, {TextTransparency = 0}):Play()
            TweenService:Create(SubmitBackground, transparencyTweenInfo, {BackgroundTransparency = 0}):Play()
