            TweenService:Create(RandomStuff, transparencyTweenInfo, {TextTransparency = 0}):Play()
        end)
    end

    local function minimizeDesktop()
        isMinimized = true

        local transparencyTweenInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

        TweenService:Create(UserSection, transparencyTweenInfo, {BackgroundTransparency = 1}):Play()
        TweenService:Create(UserSectionStroke, transparencyTweenInfo, {Transparency = 1}):Play()
