                Size = UDim2.new(0, 400, 0, 40)
            })
            sizeTween:Play()
        end)
    end

    local function minimizeMobile()
        isMinimized = true
        BFrame.Visible = false
        MinimizeMobileButton.Visible = true
    end

    local function restoreMobile()
        isMinimized = false
        BFrame.Visible = true
        MinimizeMobileButton.Visible = false
        local tweenInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local tween = TweenService:Create(BFrame, tweenInfo, {
            Size = UDim2.new(0, 400, 0, 211),
            BackgroundTransparency = 0
        })
        tween:Play()
    end

    MinimizeButton.MouseButton1Click:Connect(function()
	if isMinimized then
		if isMobile then
			restoreMobile()
		else
			restoreDesktop()
		end
	else
		if isMobile then
			minimizeMobile()
		else
			minimizeDesktop()
		end
	end
end)

do
	local mobileBtn = MinimizeMobileButton
	local dragging = false
	local dragInput
	local startPos
	local startInput
	local hasMoved = false
	local DRAG_THRESHOLD = 5

	mobileBtn.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			hasMoved = false
			startInput = input.Position
			startPos = mobileBtn.Position
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
					if not hasMoved and isMinimized then
						restoreMobile()
					end
				end
			end)
		end
	end)

	mobileBtn.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			dragInput = input
		end
	end)

	UIS.InputChanged:Connect(function(input)
		if dragging and input == dragInput then
			local delta = input.Position - startInput
			if math.abs(delta.X) > DRAG_THRESHOLD or math.abs(delta.Y) > DRAG_THRESHOLD then
				hasMoved = true
			end
			if hasMoved then
				mobileBtn.Position = UDim2.new(
					startPos.X.Scale,
					startPos.X.Offset + delta.X,
					startPos.Y.Scale,
					startPos.Y.Offset + delta.Y
				)
			end
		end
	end)
end

    CloseButton.MouseButton1Click:Connect(function()
        getgenv().UI_CLOSED = true
        KeySystem:Destroy()
    end)

    DiscordButton.MouseButton1Click:Connect(function()
        setclipboard("https://discord.gg/rw4YzxnUhp")
        DebugDesc.Text = "Discord link copied!"
        DebugDesc.TextColor3 = Color3.fromRGB(100, 200, 255)
    end)

    local function saveKey(key)
        pcall(function()
            if not isfolder("Oshiru") then
                makefolder("Oshiru")
            end
            writefile("Oshiru/Key.txt", key)
        end)
    end

    local function loadSavedKey()
        local key = nil
        pcall(function()
            if isfolder and isfolder("Oshiru") then
                if isfile and isfile("Oshiru/Key.txt") then
                    key = readfile("Oshiru/Key.txt")
                end
            end
        end)
        return key
    end

    local function clearSavedKey()
        pcall(function()
            if isfile and isfile("Oshiru/Key.txt") then
                delfile("Oshiru/Key.txt")
            end
        end)
    end

    GetKeyButton.MouseButton1Click:Connect(function()
        local keyLink = Junkie.get_key_link()
        if keyLink then
            setclipboard(keyLink)
            DebugDesc.Text = "Link copied to clipboard!"
            DebugDesc.TextColor3 = Color3.fromRGB(100, 200, 255)
        else
            DebugDesc.Text = "Could not get key link"
            DebugDesc.TextColor3 = Color3.fromRGB(255, 100, 100)
        end
    end)

    SubmitButton.MouseButton1Click:Connect(function()
        local inputKey = getTextBoxKey()
        if inputKey == "" or inputKey == nil then
            DebugDesc.Text = "Please enter a key!"
            DebugDesc.TextColor3 = Color3.fromRGB(255, 100, 100)
            return
        end
        local checking = true
        local dots = 0
        local startTime = tick()
        while checking and tick() - startTime < 5 do
            dots = (dots % 3) + 1
            local dotStr = string.rep(".", dots)
            DebugDesc.Text = "Checking key" .. dotStr
            DebugDesc.TextColor3 = Color3.fromRGB(255, 255, 255)
            task.wait(0.3)
        end
        local success, checkResult = pcall(function()
            return Junkie.check_key(inputKey)
        end)
        if not success then
            DebugDesc.Text = "Error"
            DebugDesc.TextColor3 = Color3.fromRGB(255, 100, 100)
            return
        end
        if checkResult and checkResult.valid then
            DebugDesc.Text = "Valid key!"
            DebugDesc.TextColor3 = Color3.fromRGB(100, 255, 100)
            saveKey(inputKey)
            task.wait(2)
            getgenv().SCRIPT_KEY = inputKey
            getgenv().UI_CLOSED = true
            KeySystem:Destroy()
        else
            DebugDesc.Text = "Invalid key, please recheck your key!"
            DebugDesc.TextColor3 = Color3.fromRGB(255, 100, 100)
        end
    end)

    local function preloadAndShowUI()
        local instancesToPreload = {}
        for _, imageId in ipairs(imagesToPreload) do
            if imageId and imageId ~= "" then
                local img = Instance.new("ImageLabel")
                img.Image = imageId
                table.insert(instancesToPreload, img)
            end
        end

        pcall(function()
            ContentProvider:PreloadAsync(instancesToPreload)
        end)

        for _, inst in ipairs(instancesToPreload) do
            inst:Destroy()
        end

        populateSupportedGames()
        KeySystem.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
        KeySystem.Enabled = true
    end

    local initialResult = nil
    pcall(function()
        initialResult = Junkie.check_key(nil)
    end)
    if initialResult and initialResult.valid and initialResult.message == "KEYLESS" then
        getgenv().SCRIPT_KEY = "KEYLESS"
        getgenv().UI_CLOSED = true
        return getgenv().SCRIPT_KEY
    end

    addSupportedGame("Blade Ball", "rbxassetid://120185315613466")
    addSupportedGame("[FPS] Flick", "rbxassetid://76176516205125")
    addSupportedGame("Uma Racing", "rbxassetid://101019281934322")

    preloadAndShowUI()
    local savedKey = loadSavedKey()
    if savedKey and savedKey ~= "" then
        local savedResult = nil
        pcall(function()
            savedResult = Junkie.check_key(savedKey)
        end)
        if savedResult and savedResult.valid then
            inputKeyFull = savedKey
            TextBox.Text = truncateKey(savedKey)
        else
            clearSavedKey()
        end
    end

    while not getgenv().UI_CLOSED do
        task.wait(0.1)
    end
    return getgenv().SCRIPT_KEY
end)()

